INSERT OR IGNORE INTO categories (id, slug, name, blurb, sort) VALUES (1, 'notebooks', 'دفتر و کاغذ', 'دفتر سیمی، دفتر نقطه‌ای، دفتر یادداشت و کاغذ رنگی برای مدرسه، دانشگاه و محل کار.', 0);
