INSERT OR IGNORE INTO categories (id, slug, name, blurb, sort) VALUES (3, 'colors-markers', 'ماژیک و رنگ', 'مدادرنگی، ماژیک هایلایتر و وایت‌برد برای نقاشی، خلاصه‌نویسی و کلاس.', 2);
