INSERT OR IGNORE INTO products (id, slug, name, brand, cat_id, price, old_price, stock, description, image, art, color, bg, rating, reviews) VALUES (1, 'spiral-notebook-a5', 'دفتر سیمی ۱۰۰ برگ A5', 'نارون', 1, 78000, NULL, 40, 'کاغذ ۷۰ گرمی، جلد سخت و سیم دوبل. مناسب یادداشت‌برداری روزانه و کلاس.', '', 'book', '#2F54EB', '#E6ECFF', 4.7, 182);
