INSERT OR IGNORE INTO products (id, slug, name, brand, cat_id, price, old_price, stock, description, image, art, color, bg, rating, reviews) VALUES (3, 'colored-paper-a4', 'کاغذ A4 رنگی ۵۰ برگ', 'نارون', 1, 95000, NULL, 60, 'پنج رنگ شاد ۸۰ گرمی، مناسب کاردستی و پروژه‌های مدرسه‌ای.', '', 'paper', '#EB5C8A', '#FFE3EC', 4.3, 64);
