INSERT OR IGNORE INTO products (id, slug, name, brand, cat_id, price, old_price, stock, description, image, art, color, bg, rating, reviews) VALUES (5, 'hb-pencil-12', 'مداد HB بسته ۱۲ تایی', 'نارون', 2, 72000, NULL, 90, 'مغز مقاوم در برابر شکستن، مناسب نوشتن و طراحی.', '', 'pencil', '#F2B705', '#FFF1C2', 4.5, 310);
